#include <cstddef>
#include <cstdint>
#include <cstring>
#include <map>
#include <string>

enum : int32_t { QUARRY_OK = 0, QUARRY_INVALID_ARGUMENT = 1, QUARRY_NOT_FOUND = 2, QUARRY_UNSUPPORTED = 3 };
struct quarry_options { uint32_t size; int32_t capacity; int32_t depth; };
typedef struct quarry quarry;
struct quarry_api
{
    uint32_t size;
    uint32_t version;
    int32_t (*create)(const quarry_options* options, quarry** out);
    void    (*destroy)(quarry* q);
    int32_t (*dig)(quarry* q, const char* stone);
    int32_t (*count)(const quarry* q, const char* stone, int32_t* out);
    int32_t (*depth)(const quarry* q, int32_t* out);
};

struct quarry
{
    int32_t capacity{ 0 };
    int32_t depth{ 3 };
    int32_t total{ 0 };
    std::map<std::string, int32_t> stones;
};

namespace
{
    thread_local std::string t_error;

    int32_t fail(int32_t code, std::string message) { t_error = std::move(message); return code; }

    template <typename T>
    bool has(const quarry_options* o, T quarry_options::* member, std::size_t offset) { (void)member; return o->size >= offset + sizeof(T); }

    int32_t create(const quarry_options* options, quarry** out)
    {
        if (!options) return fail(QUARRY_INVALID_ARGUMENT, "options must not be null");
        if (!out) return fail(QUARRY_INVALID_ARGUMENT, "out must not be null");
        if (!has(options, &quarry_options::capacity, offsetof(quarry_options, capacity))) return fail(QUARRY_INVALID_ARGUMENT, "options.size is too small");
        if (options->capacity < 1) return fail(QUARRY_INVALID_ARGUMENT, "capacity must be at least 1");
        const int32_t depth{ has(options, &quarry_options::depth, offsetof(quarry_options, depth)) ? options->depth : 3 };
        if (depth < 1) return fail(QUARRY_INVALID_ARGUMENT, "depth must be at least 1");
        *out = new quarry{ options->capacity, depth, 0, {} };
        return QUARRY_OK;
    }

    void destroy(quarry* q) { delete q; }

    int32_t dig(quarry* q, const char* stone)
    {
        if (!q) return fail(QUARRY_INVALID_ARGUMENT, "q must not be null");
        if (!stone || !*stone) return fail(QUARRY_INVALID_ARGUMENT, "stone must not be null or empty");
        if (q->total + 1 > q->capacity) return fail(QUARRY_UNSUPPORTED, "quarry is full");
        ++q->stones[stone];
        ++q->total;
        return QUARRY_OK;
    }

    int32_t count(const quarry* q, const char* stone, int32_t* out)
    {
        if (!q) return fail(QUARRY_INVALID_ARGUMENT, "q must not be null");
        if (!stone) return fail(QUARRY_INVALID_ARGUMENT, "stone must not be null");
        if (!out) return fail(QUARRY_INVALID_ARGUMENT, "out must not be null");
        const auto it{ q->stones.find(stone) };
        if (it == q->stones.end()) return fail(QUARRY_NOT_FOUND, std::string("no ") + stone + " was dug");
        *out = it->second;
        return QUARRY_OK;
    }

    int32_t depth(const quarry* q, int32_t* out)
    {
        if (!q) return fail(QUARRY_INVALID_ARGUMENT, "q must not be null");
        if (!out) return fail(QUARRY_INVALID_ARGUMENT, "out must not be null");
        *out = q->depth;
        return QUARRY_OK;
    }

    const quarry_api g_v1{ static_cast<uint32_t>(offsetof(quarry_api, depth)), 1, create, destroy, dig, count, nullptr };
    const quarry_api g_v2{ static_cast<uint32_t>(sizeof(quarry_api)), 2, create, destroy, dig, count, depth };
}

extern "C" uint32_t quarry_version() { return (2u << 22) | (1u << 12) | 0u; }

extern "C" const quarry_api* quarry_get_api(uint32_t major)
{
    if (major == 1) return &g_v1;
    if (major == 2) return &g_v2;
    return nullptr;
}

extern "C" int32_t quarry_last_error(char* buffer, int32_t capacity)
{
    const int32_t length{ static_cast<int32_t>(t_error.size()) };
    if (buffer && capacity >= 1)
    {
        const int32_t copy{ length < capacity - 1 ? length : capacity - 1 };
        std::memcpy(buffer, t_error.data(), static_cast<std::size_t>(copy));
        buffer[copy] = '\0';
    }
    return length;
}

unitTests:
std::string err() { std::string s(static_cast<std::size_t>(quarry_last_error(nullptr, 0)), '\0'); quarry_last_error(s.data(), static_cast<int32_t>(s.size()) + 1); return s; }
TEST("version") { CHECK_EQ(quarry_version() >> 22, 2u); CHECK_EQ((quarry_version() >> 12) & 0x3FF, 1u); CHECK_EQ(quarry_version() & 0xFFF, 0u); }
TEST("tables") {
    const quarry_api* v1 = quarry_get_api(1); const quarry_api* v2 = quarry_get_api(2);
    CHECK(v1 != nullptr); CHECK(v2 != nullptr); CHECK(quarry_get_api(3) == nullptr); CHECK(quarry_get_api(0) == nullptr);
    CHECK_EQ(v1->version, 1u); CHECK_EQ(v2->version, 2u);
    CHECK(v1->size <= offsetof(quarry_api, depth)); CHECK(v1->size >= offsetof(quarry_api, count) + sizeof(void*));
    CHECK_EQ(v2->size, static_cast<uint32_t>(sizeof(quarry_api)));
}
TEST("a version 2 program") {
    const quarry_api* api = quarry_get_api(2);
    quarry_options o{ sizeof(quarry_options), 3, 7 }; quarry* q = nullptr;
    CHECK_EQ(api->create(&o, &q), QUARRY_OK);
    CHECK_EQ(api->dig(q, "basalt"), QUARRY_OK); CHECK_EQ(api->dig(q, "basalt"), QUARRY_OK); CHECK_EQ(api->dig(q, "slate"), QUARRY_OK);
    int32_t n = 0; CHECK_EQ(api->count(q, "basalt", &n), QUARRY_OK); CHECK_EQ(n, 2);
    int32_t d = 0; CHECK_EQ(api->depth(q, &d), QUARRY_OK); CHECK_EQ(d, 7);
    CHECK_EQ(api->dig(q, "slate"), QUARRY_UNSUPPORTED); CHECK_EQ(err(), std::string("quarry is full"));
    api->destroy(q);
}
TEST("a version 1 program") {
    const quarry_api* api = quarry_get_api(1);
    quarry_options o{ static_cast<uint32_t>(offsetof(quarry_options, depth)), 5, -99 }; quarry* q = nullptr;
    CHECK_EQ(api->create(&o, &q), QUARRY_OK);
    const quarry_api* v2 = quarry_get_api(2); int32_t d = 0; v2->depth(q, &d); CHECK_EQ(d, 3);
    api->destroy(q);
}
TEST("bad arguments and messages") {
    const quarry_api* api = quarry_get_api(2);
    quarry* q = nullptr; quarry_options tiny{ 4, 5, 1 }; CHECK_EQ(api->create(&tiny, &q), QUARRY_INVALID_ARGUMENT);
    quarry_options zero{ sizeof(quarry_options), 0, 1 }; CHECK_EQ(api->create(&zero, &q), QUARRY_INVALID_ARGUMENT);
    quarry_options shallow{ sizeof(quarry_options), 2, 0 }; CHECK_EQ(api->create(&shallow, &q), QUARRY_INVALID_ARGUMENT);
    CHECK_EQ(api->create(nullptr, &q), QUARRY_INVALID_ARGUMENT);
    CHECK_EQ(api->dig(nullptr, "x"), QUARRY_INVALID_ARGUMENT); CHECK_EQ(err(), std::string("q must not be null"));
    quarry_options ok{ sizeof(quarry_options), 2, 1 }; CHECK_EQ(api->create(&ok, &q), QUARRY_OK);
    int32_t n = 0; CHECK_EQ(api->count(q, "granite", &n), QUARRY_NOT_FOUND); CHECK(!err().empty());
    CHECK_EQ(api->dig(q, ""), QUARRY_INVALID_ARGUMENT);
    api->destroy(q);
}

